/// The output is over. An end bounded by the drain or by `within` comes without the end of file that would
/// report a drop still pending on a stream: it is a hole all the same.
fn finished(shared: &Shared, kept: [Vec<u8>; 2], pending: [u64; 2]) -> Collected {
    let failed = (0..2)
        .find(|&slot| pending[slot] > 0)
        .map(|slot| Error::output_lost(shared.streams[slot], pending[slot]));
    collected(shared.text, kept, None, failed)
}

/// The claim of a collection: once it is over (returned, or its future dropped, even unpolled), the output
/// has no consumer any more.
pub(super) struct Release<'a>(&'a Shared);

impl Drop for Release<'_> {
    fn drop(&mut self) {
        self.0.detach([0; 2]);
    }

/// Backpressure (WP-H, before any claim): while a consumer is attached, a full stream stops being read
/// instead of dropping; the pipe fills and the child blocks. `end()` (the tree is stopped or gone) and
/// detaching release the readers, so `wait()` and `stop()` never depend on the consumer.
pub(crate) fn hold(&self) {
    self.shared.hold();
}

/// Claims the single consumer, as chunks.
pub(crate) fn output(&self) -> Result<Output, Error> {
    self.shared.claim(Claim::Attached)?;
    Ok(Output::new(Arc::clone(&self.shared)))
}

/// Claims the single consumer, as lines (always text).
pub(crate) fn lines(&self) -> Result<Lines, Error> {
